370→// AreHooksInstalled checks if Entire hooks are installed.
371→func (c *ClaudeCodeAgent) AreHooksInstalled(ctx context.Context) bool {
372→	// Use repo root to find .claude directory when run from a subdirectory
373→	repoRoot, err := paths.WorktreeRoot(ctx)
374→	if err != nil {
375→		repoRoot = "." // Fallback to CWD if not in a git repo
376→	}
377→	settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
378→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
379→	if err != nil {
380→		return false
381→	}
382→
383→	var settings ClaudeSettings
384→	if err := json.Unmarshal(data, &settings); err != nil {
385→		return false
386→	}
387→
388→	// Check for at least one of our hooks (new or old format)
389→	return hookCommandExists(settings.Hooks.Stop, "entire hooks claude-code stop") ||
390→		hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code stop") ||
391→		// Backwards compatibility: check for old hook formats
392→		hookCommandExists(settings.Hooks.Stop, "entire hooks claudecode stop") ||
393→		hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claudecode stop") ||
394→		hookCommandExists(settings.Hooks.Stop, "entire rewind claude-hook --stop") ||
395→		hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go rewind claude-hook --stop")
396→}
397→
398→// Helper functions for hook management
399→
400→func hookCommandExists(matchers []ClaudeHookMatcher, command string) bool {
401→	for _, matcher := range matchers {
402→		for _, hook := range matcher.Hooks {
403→			if hook.Command == command {
404→				return true
405→			}
406→		}
407→	}
408→	return false
409→}
410→
411→func hookCommandExistsWithMatcher(matchers []ClaudeHookMatcher, matcherName, command string) bool {
412→	for _, matcher := range matchers {
413→		if matcher.Matcher == matcherName {
414→			for _, hook := range matcher.Hooks {
415→				if hook.Command == command {
416→					return true
417→				}
418→			}
419→		}
420→	}
421→	return false
422→}
423→
424→func addHookToMatcher(matchers []ClaudeHookMatcher, matcherName, command string) []ClaudeHookMatcher {
425→	entry := ClaudeHookEntry{
426→		Type:    "command",
427→		Command: command,
428→	}
429→
430→	// If no matcher name, add to a matcher with empty string
431→	if matcherName == "" {
432→		for i, matcher := range matchers {
433→			if matcher.Matcher == "" {
434→				matchers[i].Hooks = append(matchers[i].Hooks, entry)
435→				return matchers
436→			}
437→		}
438→		return append(matchers, ClaudeHookMatcher{
439→			Matcher: "",
440→			Hooks:   []ClaudeHookEntry{entry},
441→		})
442→	}
443→
444→	// Find or create matcher with the given name
445→	for i, matcher := range matchers {
446→		if matcher.Matcher == matcherName {
447→			matchers[i].Hooks = append(matchers[i].Hooks, entry)
448→			return matchers
449→		}
450→	}
451→
452→	return append(matchers, ClaudeHookMatcher{
453→		Matcher: matcherName,
454→		Hooks:   []ClaudeHookEntry{entry},
455→	})
456→}
457→
458→// isEntireHook checks if a command is an Entire hook (old or new format)
459→func isEntireHook(command string) bool {
460→	for _, prefix := range entireHookPrefixes {
461→		if strings.HasPrefix(command, prefix) {
462→			return true
463→		}
464→	}
465→	return false
466→}
467→
468→// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
469→func removeEntireHooks(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
470→	result := make([]ClaudeHookMatcher, 0, len(matchers))
471→	for _, matcher := range matchers {
472→		filteredHooks := make([]ClaudeHookEntry, 0, len(matcher.Hooks))
473→		for _, hook := range matcher.Hooks {
474→			if !isEntireHook(hook.Command) {
475→				filteredHooks = append(filteredHooks, hook)
476→			}
477→		}
478→		// Only keep the matcher if it has hooks remaining
479→		if len(filteredHooks) > 0 {
480→			matcher.Hooks = filteredHooks
481→			result = append(result, matcher)
482→		}
483→	}
484→	return result
485→}
486→
487→// removeEntireHooksFromMatchers removes Entire hooks from tool-use matchers (PreToolUse, PostToolUse)
488→// This handles the nested structure where hooks are grouped by tool matcher (e.g., "Task", "TodoWrite")
489→func removeEntireHooksFromMatchers(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
490→	// Same logic as removeEntireHooks - both work on the same structure
491→	return removeEntireHooks(matchers)
492→}
