package strategy

import (
	"context"
	"fmt"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
)

// Shadow strategy session state methods.
// Uses session.StateStore for persistence.

// loadSessionState loads session state using the StateStore.
func (s *ManualCommitStrategy) loadSessionState(ctx context.Context, sessionID string) (*SessionState, error) {
	store, err := s.getStateStore(ctx)
	if err != nil {
		return nil, err
	}
	state, err := store.Load(ctx, sessionID)
	if err != nil {
		return nil, fmt.Errorf("failed to load session state: %w", err)
	}

package session

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/validation"
)

const (
	// SessionStateDirName is the directory name for session state files within git common dir.
	SessionStateDirName = "entire-sessions"

	// StaleSessionThreshold is the duration after which an ended session is considered stale
	// and will be automatically deleted during load/list operations.
	StaleSessionThreshold = 7 * 24 * time.Hour
)

// State represents the state of an active session.
// This is stored in .git/entire-sessions/<session-id>.json
type State struct {
	// SessionID is the unique session identifier
	SessionID string `json:"session_id"`

	// CLIVersion is the version of the CLI that created this session
	CLIVersion string `json:"cli_version,omitempty"`

	// BaseCommit tracks the current shadow branch base. Initially set to HEAD when the
	// session starts, but updated on migration (pull/rebase) and after condensation.
	// Used for shadow branch naming and checkpoint storage — NOT for attribution.
	BaseCommit string `json:"base_commit"`

	// AttributionBaseCommit is the commit used as the reference point for attribution calculations.
	// Unlike BaseCommit (which tracks the shadow branch and moves with migration), this field
	// preserves the original base commit so deferred condensation can correctly calculate
	// agent vs human line attribution. Updated only after successful condensation.
	AttributionBaseCommit string `json:"attribution_base_commit,omitempty"`

	// WorktreePath is the absolute path to the worktree root
	WorktreePath string `json:"worktree_path,omitempty"`

	// WorktreeID is the internal git worktree identifier (empty for main worktree)
	// Derived from .git/worktrees/<name>/, stable across git worktree move
	WorktreeID string `json:"worktree_id,omitempty"`

	// StartedAt is when the session was started
	StartedAt time.Time `json:"started_at"`

	// EndedAt is when the session was explicitly closed by the user.
	// nil means the session is still active or was not cleanly closed.
	EndedAt *time.Time `json:"ended_at,omitempty"`

	// Phase is the lifecycle stage of this session (see phase.go).
	// Empty means idle (backward compat with pre-state-machine files).
	Phase Phase `json:"phase,omitempty"`

	// TurnID is a unique identifier for the current agent turn.
	// Lifecycle:
	//   - Generated fresh in InitializeSession at each turn start
	//   - Shared across all checkpoints within the same turn
	//   - Used to correlate related checkpoints when a turn's work spans multiple commits
	//   - Persists until the next InitializeSession call generates a new one
	TurnID string `json:"turn_id,omitempty"`

	// TurnCheckpointIDs tracks all checkpoint IDs condensed during the current turn.
	// Lifecycle:
	//   - Set in PostCommit when a checkpoint is condensed for an ACTIVE session

//   - Set in PostCommit when a checkpoint is condensed for an ACTIVE session
//   - Consumed in HandleTurnEnd to finalize all checkpoints with the full transcript
//   - Cleared in HandleTurnEnd after finalization completes
//   - Cleared in InitializeSession when a new prompt starts
//   - Cleared when session is reset (ResetSession deletes the state file entirely)
TurnCheckpointIDs []string `json:"turn_checkpoint_ids,omitempty"`

// LastInteractionTime is updated on agent-interaction events (TurnStart,
// TurnEnd, SessionStop, Compaction) but NOT on git commit hooks.
// Used for stale session detection in "entire doctor".
LastInteractionTime *time.Time `json:"last_interaction_time,omitempty"`

// StepCount is the number of checkpoints/steps created in this session.
// JSON tag kept as "checkpoint_count" for backward compatibility with existing state files.
StepCount int `json:"checkpoint_count"`

// CheckpointTranscriptStart is the transcript line offset where the current
// checkpoint cycle began. Set to 0 at session start, updated to current
// transcript length after each condensation. Used to scope the transcript
// for checkpoint condensation: "everything since last checkpoint".
CheckpointTranscriptStart int `json:"checkpoint_transcript_start,omitempty"`

// Deprecated: CondensedTranscriptLines is replaced by CheckpointTranscriptStart.
// Kept for backward compatibility with existing state files.
// Use NormalizeAfterLoad() to migrate.
CondensedTranscriptLines int `json:"condensed_transcript_lines,omitempty"`

// UntrackedFilesAtStart tracks files that existed at session start (to preserve during rewind)
UntrackedFilesAtStart []string `json:"untracked_files_at_start,omitempty"`

// FilesTouched tracks files modified/created/deleted during this session
FilesTouched []string `json:"files_touched,omitempty"`

// LastCheckpointID is the checkpoint ID from the most recent condensation.
// Used to restore the Entire-Checkpoint trailer on amend and to identify
// sessions that have been condensed at least once. Cleared on new prompt.
LastCheckpointID id.CheckpointID `json:"last_checkpoint_id,omitempty"`

// FullyCondensed indicates this session has been condensed and has no remaining
// carry-forward files. PostCommit skips fully-condensed sessions entirely.
// Set after successful condensation when no files remain for carry-forward
// and the session phase is ENDED. Cleared on session reactivation (ENDED →
// ACTIVE via TurnStart, or ENDED → IDLE via SessionStart) by ActionClearEndedAt.
FullyCondensed bool `json:"fully_condensed,omitempty"`

// AgentType identifies the agent that created this session (e.g., "Claude Code", "Gemini CLI", "Cursor")
AgentType types.AgentType `json:"agent_type,omitempty"`

// ModelName is the LLM model used in this session (e.g., "claude-sonnet-4-20250514", "gpt-4o").
// Set from hook data when the agent provides it.
ModelName string `json:"model_name,omitempty"`

// Token usage tracking (accumulated across all checkpoints in this session)
TokenUsage *agent.TokenUsage `json:"token_usage,omitempty"`

// Hook-provided session metrics (for agents like Cursor that report via hooks)
SessionDurationMs int64 `json:"session_duration_ms,omitempty"`
SessionTurnCount  int   `json:"session_turn_count,omitempty"`
ContextTokens     int   `json:"context_tokens,omitempty"`
ContextWindowSize int   `json:"context_window_size,omitempty"`

// Deprecated: TranscriptLinesAtStart is replaced by CheckpointTranscriptStart.
// Kept for backward compatibility with existing state files.
TranscriptLinesAtStart int `json:"transcript_lines_at_start,omitempty"`

// TranscriptIdentifierAtStart is the last transcript identifier when the session started.
// Used for identifier-based transcript scoping (UUID for Claude, message ID for Gemini).
TranscriptIdentifierAtStart string `json:"transcript_identifier_at_start,omitempty"`

// TranscriptPath is the path to the live transcript file (for mid-session commit detection)
TranscriptPath string `json:"transcript_path,omitempty"`

// LastPrompt is the most recent user prompt for this session (truncated for display).
// Updated on every turn start (UserPromptSubmit). JSON tag kept as "first_prompt"
// for backward compatibility with existing state files.
LastPrompt string `json:"last_prompt,omitempty"`

// PromptAttributions tracks user and agent line changes at each prompt start.
// This enables accurate attribution by capturing user edits between checkpoints.
PromptAttributions []PromptAttribution `json:"prompt_attributions,omitempty"`

content.content:
  1→package claudecode
  2→
  3→import (
  4→	"context"
  5→	"encoding/json"
  6→	"fmt"
  7→	"os"
  8→	"path/filepath"
  9→	"slices"
 10→	"strings"
 11→
 12→	"github.com/entireio/cli/cmd/entire/cli/agent"
 13→	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
 14→	"github.com/entireio/cli/cmd/entire/cli/paths"
 15→)
 16→
 17→// Ensure ClaudeCodeAgent implements HookSupport
 18→var _ agent.HookSupport = (*ClaudeCodeAgent)(nil)
 19→
 20→// Claude Code hook names - these become subcommands under `entire hooks claude-code`
 21→const (
 22→	HookNameSessionStart     = "session-start"
 23→	HookNameSessionEnd       = "session-end"
 24→	HookNameStop             = "stop"
 25→	HookNameUserPromptSubmit = "user-prompt-submit"
 26→	HookNamePreTask          = "pre-task"
 27→	HookNamePostTask         = "post-task"
 28→	HookNamePostTodo         = "post-todo"
 29→)
 30→
 31→// ClaudeSettingsFileName is the settings file used by Claude Code.
 32→// This is Claude-specific and not shared with other agents.
 33→const ClaudeSettingsFileName = "settings.json"
 34→
 35→// metadataDenyRule blocks Claude from reading Entire session metadata
 36→const metadataDenyRule = "Read(./.entire/metadata/**)"
 37→
 38→// entireHookPrefixes are command prefixes that identify Entire hooks (both old and new formats)
 39→var entireHookPrefixes = []string{
 40→	"entire ",
 41→	"go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go ",
 42→}
 43→
 44→// InstallHooks installs Claude Code hooks in .claude/settings.json.
 45→// If force is true, removes existing Entire hooks before installing.
 46→// Returns the number of hooks installed.
 47→func (c *ClaudeCodeAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
 48→	// Use repo root instead of CWD to find .claude directory
 49→	// This ensures hooks are installed correctly when run from a subdirectory
 50→	repoRoot, err := paths.WorktreeRoot(ctx)
 51→	if err != nil {
 52→		// Fallback to CWD if not in a git repo (e.g., during tests)
 53→		repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests run outside git repos)
 54→		if err != nil {
 55→			return 0, fmt.Errorf("failed to get current directory: %w", err)
 56→		}
 57→	}
 58→
 59→	settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
 60→
 61→	// Read existing settings if they exist
 62→	var rawSettings map[string]json.RawMessage
 63→
 64→	// rawHooks preserves unknown hook types (e.g., "Notification", "SubagentStop")
 65→	var rawHooks map[string]json.RawMessage
 66→
 67→	// rawPermissions preserves unknown permission fields (e.g., "ask")
 68→	var rawPermissions map[string]json.RawMessage
 69→
 70→	existingData, readErr := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + settings file name
 71→	if readErr == nil {
 72→		if err := json.Unmarshal(existingData, &rawSettings); err != nil {
 73→			return 0, fmt.Errorf("failed to parse existing settings.json: %w", err)
 74→		}
 75→		if hooksRaw, ok := rawSettings["hooks"]; ok {
 76→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 77→				return 0, fmt.Errorf("failed to parse hooks in settings.json: %w", err)
 78→			}
 79→		}
 80→		if permRaw, ok := rawSettings["permissions"]; ok {
 81→			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
 82→				return 0, fmt.Errorf("failed to parse permissions in settings.json: %w", err)
 83→			}
 84→		}
 85→	} else {
 86→		rawSettings = make(map[string]json.RawMessage)
 87→	}
 88→
 89→	if rawHooks == nil {
 90→		rawHooks = make(map[string]json.RawMessage)
 91→	}
 92→	if rawPermissions == nil {
 93→		rawPermissions = make(map[string]json.RawMessage)
 94→	}
 95→
 96→	// Parse only the hook types we need to modify
 97→	var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
 98→	parseHookType(rawHooks, "SessionStart", &sessionStart)
 99→	parseHookType(rawHooks, "SessionEnd", &sessionEnd)
100→	parseHookType(rawHooks, "Stop", &stop)
101→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
102→	parseHookType(rawHooks, "PreToolUse", &preToolUse)
103→	parseHookType(rawHooks, "PostToolUse", &postToolUse)
104→
105→	// If force is true, remove all existing Entire hooks first
106→	if force {
107→		sessionStart = removeEntireHooks(sessionStart)
108→		sessionEnd = removeEntireHooks(sessionEnd)
109→		stop = removeEntireHooks(stop)
110→		userPromptSubmit = removeEntireHooks(userPromptSubmit)
111→		preToolUse = removeEntireHooksFromMatchers(preToolUse)
112→		postToolUse = removeEntireHooksFromMatchers(postToolUse)
113→	}
114→
115→	// Define hook commands
116→	var sessionStartCmd, sessionEndCmd, stopCmd, userPromptSubmitCmd, preTaskCmd, postTaskCmd, postTodoCmd string
117→	if localDev {
118→		sessionStartCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code session-start"
119→		sessionEndCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code session-end"
120→		stopCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code stop"
121→		userPromptSubmitCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code user-prompt-submit"
122→		preTaskCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code pre-task"
123→		postTaskCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-task"
124→		postTodoCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-todo"
125→	} else {
126→		sessionStartCmd = "entire hooks claude-code session-start"
127→		sessionEndCmd = "entire hooks claude-code session-end"
128→		stopCmd = "entire hooks claude-code stop"
129→		userPromptSubmitCmd = "entire hooks claude-code user-prompt-submit"
130→		preTaskCmd = "entire hooks claude-code pre-task"
131→		postTaskCmd = "entire hooks claude-code post-task"
132→		postTodoCmd = "entire hooks claude-code post-todo"
133→	}
134→
135→	count := 0
136→
137→	// Add hooks if they don't exist
138→	if !hookCommandExists(sessionStart, sessionStartCmd) {
139→		sessionStart = addHookToMatcher(sessionStart, "", sessionStartCmd)
140→		count++
141→	}
142→	if !hookCommandExists(sessionEnd, sessionEndCmd) {
143→		sessionEnd = addHookToMatcher(sessionEnd, "", sessionEndCmd)
144→		count++
145→	}
146→	if !hookCommandExists(stop, stopCmd) {
147→		stop = addHookToMatcher(stop, "", stopCmd)
148→		count++
149→	}
150→	if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
151→		userPromptSubmit = addHookToMatcher(userPromptSubmit, "", userPromptSubmitCmd)
152→		count++
153→	}
154→	if !hookCommandExistsWithMatcher(preToolUse, "Task", preTaskCmd) {
155→		preToolUse = addHookToMatcher(preToolUse, "Task", preTaskCmd)
156→		count++
157→	}
158→	if !hookCommandExistsWithMatcher(postToolUse, "Task", postTaskCmd) {
159→		postToolUse = addHookToMatcher(postToolUse, "Task", postTaskCmd)
160→		count++
161→	}
162→	if !hookCommandExistsWithMatcher(postToolUse, "TodoWrite", postTodoCmd) {
163→		postToolUse = addHookToMatcher(postToolUse, "TodoWrite", postTodoCmd)
164→		count++
165→	}
166→
167→	// Add permissions.deny rule if not present
168→	permissionsChanged := false
169→	var denyRules []string
170→	if denyRaw, ok := rawPermissions["deny"]; ok {
171→		if err := json.Unmarshal(denyRaw, &denyRules); err != nil {
172→			return 0, fmt.Errorf("failed to parse permissions.deny in settings.json: %w", err)
173→		}
174→	}
175→	if !slices.Contains(denyRules, metadataDenyRule) {
176→		denyRules = append(denyRules, metadataDenyRule)
177→		denyJSON, err := json.Marshal(denyRules)
178→		if err != nil {
179→			return 0, fmt.Errorf("failed to marshal permissions.deny: %w", err)
180→		}
181→		rawPermissions["deny"] = denyJSON
182→		permissionsChanged = true
183→	}
184→
185→	if count == 0 && !permissionsChanged {
186→		return 0, nil // All hooks and permissions already installed
187→	}
188→
189→	// Marshal modified hook types back to rawHooks
190→	marshalHookType(rawHooks, "SessionStart", sessionStart)
191→	marshalHookType(rawHooks, "SessionEnd", sessionEnd)
192→	marshalHookType(rawHooks, "Stop", stop)
193→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
194→	marshalHookType(rawHooks, "PreToolUse", preToolUse)
195→	marshalHookType(rawHooks, "PostToolUse", postToolUse)
196→
197→	// Marshal hooks and update raw settings
198→	hooksJSON, err := json.Marshal(rawHooks)
199→	if err != nil {
200→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
201→	}
202→	rawSettings["hooks"] = hooksJSON
203→
204→	// Marshal permissions and update raw settings
205→	permJSON, err := json.Marshal(rawPermissions)
206→	if err != nil {
207→		return 0, fmt.Errorf("failed to marshal permissions: %w", err)
208→	}
209→	rawSettings["permissions"] = permJSON
210→
211→	// Write back to file
212→	if err := os.MkdirAll(filepath.Dir(settingsPath), 0o750); err != nil {
213→		return 0, fmt.Errorf("failed to create .claude directory: %w", err)
214→	}
215→
216→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
217→	if err != nil {
218→		return 0, fmt.Errorf("failed to marshal settings: %w", err)
219→	}
220→
221→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
222→		return 0, fmt.Errorf("failed to write settings.json: %w", err)
223→	}
224→
225→	return count, nil
226→}
