 35→// TestSetupClaudeHooks_AddsAllRequiredHooks is a smoke test verifying that
 36→// `entire enable --agent claude-code` adds all required hooks to the correct file.
 37→// Detailed hook manipulation logic is tested in unit tests (setup_test.go).
 38→func TestSetupClaudeHooks_AddsAllRequiredHooks(t *testing.T) {
 39→	t.Parallel()
 40→	env := NewTestEnv(t)
 41→	env.InitRepo()
 42→	env.InitEntire() // Sets up .entire/settings.json
 43→
 44→	// Create initial commit (required for setup)
 45→	env.WriteFile("README.md", "# Test")
 46→	env.GitAdd("README.md")
 47→	env.GitCommit("Initial commit")
 48→
 49→	// Run entire enable --agent claude-code (non-interactive)
 50→	output, err := env.RunCLIWithError("enable", "--agent", "claude-code")
 51→	if err != nil {
 52→		t.Fatalf("enable claude-hooks command failed: %v\nOutput: %s", err, output)
 53→	}
 54→
 55→	// Read the generated settings.json
 56→	settings := readClaudeSettings(t, env)
 57→
 58→	// Verify all 6 hooks exist
 59→	if len(settings.Hooks.SessionStart) == 0 {
 60→		t.Error("SessionStart hook should exist")
 61→	}
 62→	if len(settings.Hooks.Stop) == 0 {
 63→		t.Error("Stop hook should exist")
 64→	}
 65→	if len(settings.Hooks.UserPromptSubmit) == 0 {
 66→		t.Error("UserPromptSubmit hook should exist")
 67→	}
 68→	if !hasHookWithMatcher(settings.Hooks.PreToolUse, "Task") {
 69→		t.Error("PreToolUse[Task] hook should exist")
 70→	}
 71→	if !hasHookWithMatcher(settings.Hooks.PostToolUse, "Task") {
 72→		t.Error("PostToolUse[Task] hook should exist")
 73→	}
 74→	if !hasHookWithMatcher(settings.Hooks.PostToolUse, "TodoWrite") {
 75→		t.Error("PostToolUse[TodoWrite] hook should exist")
 76→	}
 77→}
