 52→// ParseHookEvent translates a Claude Code hook into a normalized lifecycle Event.
 53→// Returns nil if the hook has no lifecycle significance.
 54→func (c *ClaudeCodeAgent) ParseHookEvent(_ context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
 55→	switch hookName {
 56→	case HookNameSessionStart:
 57→		return c.parseSessionStart(stdin)
 58→	case HookNameUserPromptSubmit:
 59→		return c.parseTurnStart(stdin)
 60→	case HookNameStop:
 61→		return c.parseTurnEnd(stdin)
 62→	case HookNameSessionEnd:
 63→		return c.parseSessionEnd(stdin)
 64→	case HookNamePreTask:
 65→		return c.parseSubagentStart(stdin)
 66→	case HookNamePostTask:
 67→		return c.parseSubagentEnd(stdin)
 68→	case HookNamePostTodo:
 69→		// PostTodo is Claude-specific; handled outside the generic dispatcher.
 70→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
 71→	default:
 72→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 73→	}
 74→}
