168→func (c *ClaudeCodeAgent) parseSubagentEnd(stdin io.Reader) (*agent.Event, error) {
169→	raw, err := agent.ReadAndParseHookInput[postToolHookInputRaw](stdin)
170→	if err != nil {
171→		return nil, err
172→	}
173→	event := &agent.Event{
174→		Type:       agent.SubagentEnd,
175→		SessionID:  raw.SessionID,
176→		SessionRef: raw.TranscriptPath,
177→		ToolUseID:  raw.ToolUseID,
178→		ToolInput:  raw.ToolInput,
179→		Timestamp:  time.Now(),
180→	}
181→	if raw.ToolResponse.AgentID != "" {
182→		event.SubagentID = raw.ToolResponse.AgentID
