487→		if err := json.Unmarshal(rawHooks["SessionStart"], &matchers); err != nil {
488→			t.Fatalf("failed to parse SessionStart hooks: %v", err)
489→		}
490→		assertHookExists(t, matchers, "", "echo user session start", "user SessionStart hook")
491→		assertHookExists(t, matchers, "", "entire hooks claude-code session-start", "Entire SessionStart hook")
492→	})
493→
494→	t.Run("PostToolUse", func(t *testing.T) {
495→		t.Parallel()
496→		var matchers []ClaudeHookMatcher
497→		if err := json.Unmarshal(rawHooks["PostToolUse"], &matchers); err != nil {
