499→		}
500→		assertHookExists(t, matchers, "Write", "echo user wrote file", "user Write hook")
501→		assertHookExists(t, matchers, "Task", "entire hooks claude-code post-task", "Entire Task hook")
502→		assertHookExists(t, matchers, "TodoWrite", "entire hooks claude-code post-todo", "Entire TodoWrite hook")
