506→// assertHookExists checks that a hook with the given matcher and command exists
507→func assertHookExists(t *testing.T, matchers []ClaudeHookMatcher, matcher, command, description string) {
508→	t.Helper()
509→	for _, m := range matchers {
510→		if m.Matcher == matcher {
511→			for _, h := range m.Hooks {
512→				if h.Command == command {
513→					return
514→				}
515→			}
516→		}
517→	}
518→	t.Errorf("%s was not found (matcher=%q, command=%q)", description, matcher, command)
519→}
